// Demo seed — EISA Confirmation, item 1.10. Written in the same shape as
// eisa-confirmation/api.ts (generateConfirmation, acknowledgeConfirmation, confirmDetails), with
// the audit entries and notifications each step implies. A confirmation is generated only once
// every registration for its sitting is Registered (eisaRegistration.ts); the consolidated
// learner list, centres and counts come from those registrations. Days are "days ago".
//
//  #    Sitting                       QP                   Generated by     Stage
//  F1   Electrical Trades, today+35   Nomvula Dlamini      Lindiwe Khumalo  Ready to confirm — list acknowledged, QP still to confirm
//                                                                           centres, learner counts and marking/moderation dates
//                                                                           (2 centres: Khanya Skills Academy, Thabo Technical College)
//  F2–F12  the 11 past sittings behind eisaRegistration.ts P1–P11: Confirmed, ~5 weeks before
//       each sitting, with marking 2 and moderation 7 working days after it. F2 (Electrical
//       Trades, today - 15) is the confirmed one still awaiting its results batch.
// Not seeded on purpose: Welding at today + 55 (eisaRegistration.ts G4) is Registered with no
// confirmation yet, so it is listed under "Ready to Confirm" for the Assistant Director.
import { addWorkingDays } from '../../../shared/dates/workingDays';
import type { EisaSitting } from '../../../modules/eisa-calendar/types';
import { CONFIRMATION_GENERATOR_ROLE } from '../../../modules/eisa-confirmation/config';
import { CONFIRMATION_WORKFLOW } from '../../../modules/eisa-confirmation/workflow';
import type { EisaConfirmationRecord } from '../../../modules/eisa-confirmation/types';
import type { EisaRegistrationRecord } from '../../../modules/eisa-registration/types';
import { createClock, dateOf, notify, seedId, seedPerson, step, type SeedLog } from './helpers';
import { sittingAt } from './eisaRegistration';

const CONFIRMATION_ID_GROUP = 6;
const LINDIWE = 'lindiwe-khumalo';
const RIAAN = 'riaan-pretorius';

// Assistant Directors as in eisaRegistration.ts: Riaan Pretorius for Plumbing (Lerato), Lindiwe
// Khumalo for Electrical Trades and Welding.
const PAST_SITTINGS: { title: string; offset: number; adId: string }[] = [
  { title: 'Electrical Trades', offset: -15, adId: LINDIWE },
  { title: 'Plumbing', offset: -30, adId: RIAAN },
  { title: 'Welding', offset: -45, adId: LINDIWE },
  { title: 'Plumbing', offset: -50, adId: RIAAN },
  { title: 'Electrical Trades', offset: -60, adId: LINDIWE },
  { title: 'Plumbing', offset: -75, adId: RIAAN },
  { title: 'Welding', offset: -90, adId: LINDIWE },
  { title: 'Electrical Trades', offset: -105, adId: LINDIWE },
  { title: 'Plumbing', offset: -130, adId: RIAAN },
  { title: 'Welding', offset: -150, adId: LINDIWE },
  { title: 'Electrical Trades', offset: -170, adId: LINDIWE },
];

interface ConfirmationSeedBuilder {
  acknowledge: (atDaysAgo: number) => ConfirmationSeedBuilder;
  confirm: (atDaysAgo: number) => ConfirmationSeedBuilder;
  done: () => void;
}

export function seedEisaConfirmations(log: SeedLog, sittings: EisaSitting[], registrations: EisaRegistrationRecord[]): EisaConfirmationRecord[] {
  const records: EisaConfirmationRecord[] = [];
  let n = 0;

  function generate(sitting: EisaSitting, adId: string, daysAgo: number): ConfirmationSeedBuilder {
    const clock = createClock();
    const ad = seedPerson(adId);
    if (ad.role !== CONFIRMATION_GENERATOR_ROLE) throw new Error(`Demo seed: ${ad.name} cannot generate an EISA Confirmation.`);
    const generatedAt = clock.at(daysAgo, 9);

    // generateConfirmation(): once per sitting, only from Registered registrations, and only
    // once registration is complete (every registration for the sitting is Registered).
    if (records.some((r) => r.sittingId === sitting.id)) throw new Error(`Demo seed: ${sitting.date} already has an EISA Confirmation.`);
    const forSitting = registrations.filter((r) => r.sittingId === sitting.id);
    const registered = forSitting.filter((r) => r.workflow.stageId === 'registered');
    if (registered.length === 0 || registered.length !== forSitting.length) {
      throw new Error(`Demo seed: registration is not yet complete for ${sitting.qualificationTitle} ${sitting.date}.`);
    }
    if (registered.some((r) => r.createdAt >= generatedAt)) throw new Error('Demo seed: confirmation generated before its registrations.');

    const learners = registered.flatMap((r) =>
      r.learners.map((l) => ({ learnerId: l.learnerId, fullName: l.fullName, sdpName: r.sdpName, assessmentCentre: r.sdpName })),
    );
    let record: EisaConfirmationRecord = {
      id: seedId(CONFIRMATION_ID_GROUP, ++n),
      sittingId: sitting.id,
      sittingDate: sitting.date,
      qualificationTitle: sitting.qualificationTitle,
      qpId: sitting.qpId,
      qpName: sitting.qpName,
      registrationIds: registered.map((r) => r.id),
      learners,
      centres: [...new Set(learners.map((l) => l.assessmentCentre))],
      confirmedCentres: null,
      markingDate: null,
      moderationDate: null,
      workflow: { stageId: 'awaiting-qp-ack' },
      generatedBy: ad.name,
      generatedById: ad.id,
      generatedAt,
    };
    notify(log, generatedAt, {
      recipientRole: 'QP',
      title: 'EISA Confirmation ready',
      body: `A consolidated learner list for "${sitting.qualificationTitle}" (${sitting.date}) is ready to review.`,
    });

    const qp = seedPerson(sitting.qpId);
    const api: ConfirmationSeedBuilder = {
      acknowledge(atDaysAgo: number) {
        const workflow = step(log, {
          definition: CONFIRMATION_WORKFLOW,
          state: record.workflow,
          actionId: 'conf-acknowledge',
          actor: qp,
          at: clock.at(atDaysAgo, 10),
          recordType: 'eisa-confirmation',
          recordId: record.id,
        });
        record = { ...record, workflow };
        return api;
      },
      // confirmDetails(): a count for every centre (at least 1), marking on/after the sitting,
      // moderation on/after marking.
      confirm(atDaysAgo: number) {
        const markingDate = addWorkingDays(sitting.date, 2);
        const moderationDate = addWorkingDays(sitting.date, 7);
        if (markingDate < record.sittingDate || moderationDate < markingDate) throw new Error('Demo seed: marking/moderation dates out of order.');
        const confirmedCentres = record.centres.map((centre) => ({ centre, learnerCount: learners.filter((l) => l.assessmentCentre === centre).length }));
        if (confirmedCentres.some((c) => c.learnerCount < 1)) throw new Error('Demo seed: every assessment centre needs at least one confirmed learner.');
        const at = clock.at(atDaysAgo, 11);
        const workflow = step(log, {
          definition: CONFIRMATION_WORKFLOW,
          state: record.workflow,
          actionId: 'conf-confirm',
          actor: qp,
          at,
          recordType: 'eisa-confirmation',
          recordId: record.id,
        });
        record = { ...record, workflow, confirmedCentres, markingDate, moderationDate };
        notify(log, at, {
          recipientRole: 'Assistant Director',
          title: 'EISA Confirmation complete',
          body: `"${record.qualificationTitle}" (${record.sittingDate}) is confirmed — marking ${markingDate}, moderation ${moderationDate}.`,
        });
        return api;
      },
      done() {
        records.push(record);
      },
    };
    return api;
  }

  for (const p of PAST_SITTINGS) {
    const sittingDaysAgo = -p.offset;
    generate(sittingAt(sittings, p.title, p.offset), p.adId, sittingDaysAgo + 40)
      .acknowledge(sittingDaysAgo + 37)
      .confirm(sittingDaysAgo + 35)
      .done();
  }

  // F1 — ready for the QP to confirm.
  generate(sittingAt(sittings, 'Electrical Trades', 35), LINDIWE, 12).acknowledge(6).done();

  if (records.some((r) => r.markingDate && dateOf(r.generatedAt) > r.markingDate)) throw new Error('Demo seed: a confirmation was generated after marking.');

  // Newest first, the order generateConfirmation() leaves the list in.
  return records.sort((a, b) => b.generatedAt.localeCompare(a.generatedAt));
}
